def mkdirs_perm(path, perm=None):
    """
    Recursively creates directory up to *path*. If *perm* is set, the permissions of all newly
    created directories are set to its value.
    """
    if not os.path.exists(path):
        os.mkdir(path)
        if perm is not None:
            os.chmod(path, perm)


def get_files_in_dir(path, pattern=None):
    """
    Returns a list of all files in the directory *path*.
    """
    files = []
    for root, dirs, files in os.walk(path):
        for file in files:
            if pattern is None or fnmatch.fnmatch(file, pattern):
                files.append(os.path.join(root, file))
    return files


def get_files_in_dir_by_ext(path, ext):
    """
    Returns a list of all files in the directory *path* with the extension *ext*.
    """
    return get_files_in_dir(path, pattern='*.' + ext)


def get_files_in_dir_by_exts(path, exts):
    """
    Returns a list of all files in the directory *path* with the extensions *exts*.
    """
    return get_files_in_dir(path, pattern='*.' + '*'.join(exts))


